   182	const SUBSCRIBE_SUCCESS_MESSAGE = "You're on the list! Be the first to know about new collections and new arrivals.";
   183	const SUBSCRIBE_UNAVAILABLE_MESSAGE = 'Subscription is temporarily unavailable. Please try again later.';
   184	
   185	const SubscribeSection = ({
   186	  heading,
   187	  body,
   188	  initialSubscribed = false,
   189	  privacyPolicyHref,
   190	  enableNameCapture = false,
   191	}: SubscribeSectionProps) => {
   192	  // Map the Storybook-only `initialSubscribed` flag to the success state.
   193	  // Post HPC-036, 'success' will only be reached via a confirmed Omneo response.
   194	  const [submitState, setSubmitState] = useState<SubmitState>(initialSubscribed ? 'success' : 'idle');
   195	  // Ref, not state: nothing renders from it, so a re-render on capture would be wasted.
