     1	/**
     2	 * Allow-list guard for hrefs that originate outside the codebase.
     3	 *
     4	 * Anything reaching an `href` from Contentful, a URL parameter, or a prop supplied by a
     5	 * caller we do not control has to pass through here first. `javascript:` and `data:` URLs
     6	 * execute; a protocol-relative `//host` silently leaves the site. The `(?!\/)` lookahead is
     7	 * what rejects the last case — it was a real bypass, closed in e9c2180.
     8	 *
     9	 * Allow-list rather than deny-list on purpose: a deny-list has to anticipate every scheme,
    10	 * and browsers keep adding them.
    11	 */
    12	const SAFE_HREF_RE = /^(https?:|tel:|mailto:|#|\/(?!\/))/i;
    13	
    14	/** True when `href` is safe to render on an anchor. Absent or unsafe values return false. */
    15	export const isSafeHref = (href: string | undefined): boolean => (href ? SAFE_HREF_RE.test(href) : false);

===== safeHref.test.ts =====
     1	import { describe, test, expect } from 'vitest';
     2	import { isSafeHref } from './safeHref';
     3	
     4	/**
     5	 * The guard is a security boundary — every consumer renders an anchor on its say-so — so the
     6	 * rejection cases matter more than the acceptances. `//example.com` is the one that regressed
     7	 * before (e9c2180) and is the reason the pattern carries a negative lookahead.
     8	 */
     9	describe('isSafeHref', () => {
    10	  test.each([
    11	    ['/womens', true],
    12	    ['https://zimmermann.com', true],
    13	    ['http://zimmermann.com', true],
    14	    ['tel:+61280808080', true],
    15	    ['mailto:care@zimmermann.com', true],
    16	    ['#top', true],
    17	  ])('allows %s', (href, expected) => {
    18	    expect(isSafeHref(href)).toBe(expected);
    19	  });
    20	
    21	  test.each([
    22	    ['javascript:void(0)', false],
    23	    ['JavaScript:alert(1)', false],
    24	    ['data:text/html,<script>alert(1)</script>', false],
    25	    ['//example.com', false],
    26	    ['vbscript:msgbox(1)', false],
    27	    ['', false],
    28	  ])('rejects %s', (href, expected) => {
    29	    expect(isSafeHref(href)).toBe(expected);
    30	  });
    31	
    32	  test('treats undefined as unsafe rather than throwing', () => {
    33	    expect(isSafeHref(undefined)).toBe(false);
    34	  });
    35	});

