     1	import { afterEach, describe, test, expect, vi } from 'vitest';
     2	import { renderHook, act } from '@testing-library/react';
     3	import { useZimmTextInputState } from './useZimmTextInputState';
     4	
     5	/**
     6	 * The value-ownership switch is the thing in this hook that can break without surfacing as a
     7	 * type or build error: a controlled input that silently keeps its own state looks correct
     8	 * until a parent form tries to reset it.
     9	 *
    10	 * The derived-colour cascade used to live here too. It now lives in
    11	 * `theme/components/zimmTextInput.ts` and is covered by that file's own test.
    12	 */
    13	
    14	const change = (v: string) => ({ target: { value: v } } as unknown as React.ChangeEvent<HTMLInputElement>);
    15	
    16	afterEach(() => {
    17	  vi.clearAllMocks();
    18	});
    19	
    20	describe('useZimmTextInputState — value ownership', () => {
    21	  test('is uncontrolled by default and starts empty', () => {
    22	    const { result } = renderHook(() => useZimmTextInputState({}));
    23	    expect(result.current.value).toBe('');
    24	  });
    25	
    26	  test('seeds the uncontrolled value from defaultValue', () => {
    27	    const { result } = renderHook(() => useZimmTextInputState({ defaultValue: 'seed' }));
    28	    expect(result.current.value).toBe('seed');
    29	  });
    30	
    31	  test('uncontrolled: a change updates the value and notifies the caller', () => {
    32	    const onChange = vi.fn();
    33	    const { result } = renderHook(() => useZimmTextInputState({ onChange }));
    34	    act(() => {
    35	      result.current.handleChange(change('hello'));
    36	    });
    37	    expect(result.current.value).toBe('hello');
    38	    expect(onChange).toHaveBeenCalledWith('hello');
    39	  });
    40	
    41	  test('uncontrolled: clearing resets the value and notifies with an empty string', () => {
    42	    const onChange = vi.fn();
    43	    const { result } = renderHook(() => useZimmTextInputState({ onChange, defaultValue: 'x' }));
    44	    act(() => {
    45	      result.current.handleClear();
    46	    });
    47	    expect(result.current.value).toBe('');
    48	    expect(onChange).toHaveBeenCalledWith('');
    49	  });
    50	
    51	  test('controlled: the value comes from the prop, not internal state', () => {
    52	    const { result } = renderHook(() => useZimmTextInputState({ value: 'owned' }));
    53	    expect(result.current.value).toBe('owned');
    54	  });
    55	
    56	  test('controlled: a change notifies the caller but does not move the value itself', () => {
    57	    const onChange = vi.fn();
    58	    const { result } = renderHook(() => useZimmTextInputState({ value: 'owned', onChange }));
    59	    act(() => {
    60	      result.current.handleChange(change('typed'));
    61	    });
    62	    expect(result.current.value).toBe('owned');
    63	    expect(onChange).toHaveBeenCalledWith('typed');
    64	  });
    65	
    66	  test('controlled: defaultValue is ignored', () => {
    67	    const { result } = renderHook(() => useZimmTextInputState({ value: 'owned', defaultValue: 'seed' }));
    68	    expect(result.current.value).toBe('owned');
    69	  });
    70	
    71	  test('controlled: a new prop value is reflected on re-render', () => {
    72	    const { result, rerender } = renderHook(({ value }: { value: string }) => useZimmTextInputState({ value }), {
    73	      initialProps: { value: 'first' },
    74	    });
    75	    rerender({ value: 'second' });
    76	    expect(result.current.value).toBe('second');
    77	  });
    78	});

