import type { Meta, StoryObj } from '@storybook/react-webpack5';
import React from 'react';
import { expect, fn, userEvent, within } from 'storybook/test';
import { Box } from '@chakra-ui/react';
import { ZimmInputAction } from '.';

const meta: Meta<typeof ZimmInputAction> = {
  title: 'Forms/ZimmInputAction',
  component: ZimmInputAction,
  parameters: {
    layout: 'padded',
  },
  argTypes: {
    label: { control: 'text' },
    type: { control: 'text' },
    name: { control: 'text' },
    icon: { control: 'text' },
    buttonLabel: { control: 'text' },
    errorText: { control: 'text' },
    inverse: { control: 'boolean' },
    onSubmit: { action: 'submitted' },
  },
};

export default meta;

type Story = StoryObj<typeof ZimmInputAction>;

export const Default: Story = {
  args: {
    label: 'Email address',
  },
};

export const WithSearchIcon: Story = {
  name: 'With Search Icon',
  args: {
    label: 'Search',
    icon: 'search',
  },
};

export const Error: Story = {
  args: {
    label: 'Email address',
    errorText: 'Please enter a valid email address',
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await expect(canvas.getByRole('alert')).toHaveTextContent('Please enter a valid email address');
  },
};

export const Inverse: Story = {
  args: {
    label: 'Email address',
    inverse: true,
  },
  decorators: [
    (Story) => (
      <Box bg="background.05" p="xl">
        <Story />
      </Box>
    ),
  ],
};

export const InverseError: Story = {
  name: 'Inverse + Error',
  args: {
    label: 'Email address',
    inverse: true,
    errorText: 'Please enter a valid email address',
  },
  decorators: [
    (Story) => (
      <Box bg="background.05" p="xl">
        <Story />
      </Box>
    ),
  ],
};

export const SubmitInteraction: Story = {
  name: 'Submit Interaction',
  args: {
    label: 'Email address',
    onSubmit: fn(),
  },
  play: async ({ canvasElement, args }) => {
    const canvas = within(canvasElement);
    const input = canvas.getByRole('textbox', { name: /email address/i });
    await userEvent.type(input, 'name@example.com');
    const submit = canvas.getByRole('button', { name: /submit/i });
    await userEvent.click(submit);
    await expect(args.onSubmit).toHaveBeenCalledWith('name@example.com');
  },
};

export const EmptySubmitValidation: Story = {
  name: 'Submit Validation — empty value',
  args: { label: 'Email address', type: 'email', onSubmit: fn() },
  play: async ({ canvasElement, args }) => {
    const canvas = within(canvasElement);
    await userEvent.click(canvas.getByRole('button', { name: /submit/i }));
    await expect(canvas.getByRole('alert')).toHaveTextContent(/please enter a value/i);
    await expect(args.onSubmit).not.toHaveBeenCalled();
  },
};

export const InvalidEmailValidation: Story = {
  name: 'Submit Validation — invalid email format',
  args: { label: 'Email address', type: 'email', onSubmit: fn() },
  play: async ({ canvasElement, args }) => {
    const canvas = within(canvasElement);
    await userEvent.type(canvas.getByRole('textbox', { name: /email address/i }), 'not-an-email');
    await userEvent.click(canvas.getByRole('button', { name: /submit/i }));
    await expect(canvas.getByRole('alert')).toHaveTextContent(/please enter a valid email address/i);
    await expect(args.onSubmit).not.toHaveBeenCalled();
  },
};

