import React, { useId, type CSSProperties } from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { ZimmIcon } from '../zimmIcon';
import { useZimmTextInputState } from 'app/hooks/useZimmTextInputState';

type ZimmTextInputProps = {
  label: string;
  type?: string;
  name?: string;
  inverse?: boolean;
  disabled?: boolean;
  helperText?: string;
  errorText?: string;
  onChange?: (value: string) => void;
  /** Controlled value — pass with `onChange` to let a parent form own the value. */
  value?: string;
  /** Initial value when uncontrolled. Ignored if `value` is provided. */
  defaultValue?: string;
  /**
   * Opt in to the clear-✕ shown once the field has a value. Defaults to false.
   *
   * Not in the design system: the extracted TextfieldV2 spec defines a `trailing-icon`
   * attribute and no `clearable` attribute, and SFCC-55's AC specifies the Stay in Touch
   * section as "an email input field and submit button" — two controls, not three. The
   * clear was originally added on the belief that Figma's footer glyph was an ✕; Kiera
   * confirmed (2026-08-20) it is the submit chevron, which `trailing` now carries.
   *
   * Kept as opt-in rather than deleted because a clear affordance is reasonable on a text
   * input atom (a search field would want one) — it just should not be the atom's decision
   * to impose. No consumer opts in today, so the footer renders one trailing control and
   * matches Figma.
   */
  clearable?: boolean;
  /**
   * Trailing icon-button slot. This IS in the design system: it maps to the extracted
   * TextfieldV2 spec's `trailing-icon` attribute (f2r/02-design/specs/components/text-input.md,
   * Figma node 40000265:374). ZimmInputAction injects the submit chevron here — Kiera confirmed
   * (2026-08-20) that the trailing glyph on the footer email field is the chevron, not an ✕.
   * Renders after the clear button below, which is a separate, unspecified addition.
   */
  trailing?: React.ReactNode;
  style?: CSSProperties;
};

/**
 * Atom — flush text input with floating label. Mirrors zimm-text-input contract
 * (flush + inverse variant).
 *
 * All styling lives in `theme/components/zimmTextInput.ts`. The component owns only the
 * interaction state the theme cannot express: the value, focus, and whether the field is
 * filled — `filled` and `focused` are fed back into the recipe so it can resolve the
 * Figma colour cascade and the floated-label position.
 */
export const ZimmTextInput = ({
  label,
  type = 'text',
  name,
  inverse = false,
  disabled = false,
  helperText,
  errorText,
  onChange,
  value: controlledValue,
  defaultValue,
  clearable = false,
  trailing,
  style,
}: ZimmTextInputProps) => {
  const inputId = useId();
  const helperId = `${inputId}-helper`;
  const errorId = `${inputId}-error`;
  const hasError = !!errorText;

  const { value, focused, inputRef, handleChange, handleClear, setFocused } = useZimmTextInputState({
    onChange,
    value: controlledValue,
    defaultValue,
  });

  const styles = useMultiStyleConfig('ZimmTextInput', {
    inverse,
    disabled,
    hasError,
    focused,
    filled: value.length > 0,
  });

  return (
    <chakra.div __css={styles.root} style={style}>
      <chakra.div __css={styles.row}>
        {/* content — label + input stacked */}
        <chakra.div __css={styles.content}>
          <chakra.label htmlFor={inputId} __css={styles.label}>
            {label}
          </chakra.label>
          <chakra.input
            id={inputId}
            ref={inputRef}
            type={type}
            name={name}
            value={value}
            disabled={disabled}
            autoComplete={type === 'email' ? 'email' : undefined}
            onChange={handleChange}
            onFocus={() => setFocused(true)}
            onBlur={() => setFocused(false)}
            aria-invalid={hasError}
            aria-describedby={[helperText && helperId, hasError && errorId].filter(Boolean).join(' ') || undefined}
            __css={styles.input}
          />
        </chakra.div>
        {/* Clear-✕ — opt-in only, see `clearable` above. Renders before {trailing}, so a
            field that opts into both shows clear then trailing icon. */}
        {clearable && !disabled && value.length > 0 && (
          <chakra.button type="button" aria-label="Clear input" onClick={handleClear} __css={styles.clearButton}>
            <ZimmIcon type="close" size="sm" aria-hidden={true} />
          </chakra.button>
        )}
        {trailing}
      </chakra.div>
      {helperText && (
        <chakra.p id={helperId} __css={styles.helper}>
          {helperText}
        </chakra.p>
      )}
      {errorText && (
        <chakra.p id={errorId} role="alert" __css={styles.error}>
          {errorText}
        </chakra.p>
      )}
    </chakra.div>
  );
};

import type { Meta, StoryObj } from '@storybook/react-webpack5';
import React from 'react';
import { expect, fn, userEvent, within } from 'storybook/test';
import { Box } from '@chakra-ui/react';
import { ZimmButton } from '.';
import type { ZimmIconType } from '../zimmIcon';

const ALL_ICONS: ZimmIconType[] = [
  'arrow-down',
  'arrow-link',
  'arrow-up',
  'bag',
  'bag-selected',
  'calendar',
  'carousel',
  'carousel-selected',
  'chat',
  'check',
  'chevron-down',
  'chevron-left',
  'chevron-right',
  'chevron-up',
  'close',
  'delete',
  'edit',
  'external-link',
  'info',
  'info-selected',
  'location',
  'menu',
  'minus',
  'mute',
  'password',
  'pause',
  'play',
  'plus',
  'profile',
  'search',
  'share',
  'share-2',
  'wishlist',
  'wishlist-selected',
  'phone',
  'whatsapp',
  'email',
];

const meta: Meta<typeof ZimmButton> = {
  title: 'Elements/ZimmButton',
  component: ZimmButton,
  argTypes: {
    variant: {
      control: 'select',
      options: ['primary', 'secondary', 'icon'],
    },
    // No shared `size` control: label buttons take 'large' | 'medium', icon buttons take
    // 'sm' | 'md' | 'lg'. A flat list lets you pick a pairing the component silently remaps
    // (anything but 'medium' becomes 'lg'), so the control would report the wrong answer.
    // The variant-specific stories below cover every valid combination.
    size: { table: { disable: true } },
    icon: {
      control: 'select',
      options: ALL_ICONS,
    },
    inverse: {
      control: 'boolean',
    },
    disabled: {
      control: 'boolean',
    },
    fullWidth: {
      control: 'boolean',
    },
    type: {
      control: 'radio',
      options: ['button', 'submit', 'reset'],
    },
    style: {
      control: 'object',
    },
  },
};
export default meta;

type Story = StoryObj<typeof ZimmButton>;

const inverseDecorator = [
  (Story: React.ComponentType) => (
    <Box bg="background.05" p={4} display="inline-flex">
      <Story />
    </Box>
  ),
];

// ─── Primary ────────────────────────────────────────────────────────────────

export const Default: Story = {
  args: {
    variant: 'primary',
    label: 'Button',
    size: 'large',
  },
};

export const PrimaryMedium: Story = {
  name: 'Primary — Medium',
  args: {
    variant: 'primary',
    label: 'Button',
    size: 'medium',
  },
};

export const PrimaryDisabled: Story = {
  name: 'Primary — Disabled',
  args: {
    variant: 'primary',
    label: 'Button',
    size: 'large',
    disabled: true,
  },
};

export const PrimaryInverse: Story = {
  name: 'Primary — Inverse',
  args: {
    variant: 'primary',
    label: 'Button',
    size: 'large',
    inverse: true,
  },
  decorators: inverseDecorator,
};

export const PrimaryFullWidth: Story = {
  name: 'Primary — Full Width',
  args: {
    variant: 'primary',
    label: 'Button',
    size: 'large',
    fullWidth: true,
  },
};

// ─── Secondary ──────────────────────────────────────────────────────────────

export const Secondary: Story = {
  args: {
    variant: 'secondary',
    label: 'Button',
    size: 'large',
  },
};

export const SecondaryMedium: Story = {
  name: 'Secondary — Medium',
  args: {
    variant: 'secondary',
    label: 'Button',
    size: 'medium',
  },
};

export const SecondaryDisabled: Story = {
  name: 'Secondary — Disabled',
  args: {
    variant: 'secondary',
    label: 'Button',
    size: 'large',
    disabled: true,
  },
};

export const SecondaryInverse: Story = {
  name: 'Secondary — Inverse',
  args: {
    variant: 'secondary',
    label: 'Button',
    size: 'large',
    inverse: true,
  },
  decorators: inverseDecorator,
};

// ─── Icon ───────────────────────────────────────────────────────────────────

export const Icon: Story = {
  args: {
    variant: 'icon',
    icon: 'search',
    label: 'Search',
    size: 'md',
  },
};

export const IconSmall: Story = {
  name: 'Icon — Small',
  args: {
    variant: 'icon',
    icon: 'search',
    label: 'Search',
    size: 'sm',
  },
};

export const IconLarge: Story = {
  name: 'Icon — Large',
  args: {
    variant: 'icon',
    icon: 'search',
    label: 'Search',
    size: 'lg',
  },
};

export const IconDisabled: Story = {
  name: 'Icon — Disabled',
  args: {
    variant: 'icon',
    icon: 'chevron-right',
    label: 'Next',
    size: 'md',
    disabled: true,
  },
};

export const IconInverse: Story = {
  name: 'Icon — Inverse',
  args: {
    variant: 'icon',
    icon: 'search',
    label: 'Search',
    size: 'md',
    inverse: true,
  },
  decorators: inverseDecorator,
};

// ─── Common icon use-cases ───────────────────────────────────────────────────

export const Bag: Story = {
  args: {
    variant: 'icon',
    icon: 'bag',
    label: 'Open bag',
    size: 'lg',
  },
};

export const Close: Story = {
  args: {
    variant: 'icon',
    icon: 'close',
    label: 'Close',
    size: 'md',
  },
};

export const Menu: Story = {
  args: {
    variant: 'icon',
    icon: 'menu',
    label: 'Open menu',
    size: 'lg',
  },
};

export const Wishlist: Story = {
  args: {
    variant: 'icon',
    icon: 'wishlist',
    label: 'Add to wishlist',
    size: 'lg',
  },
};

export const WishlistSelected: Story = {
  name: 'Wishlist Selected',
  args: {
    variant: 'icon',
    icon: 'wishlist-selected',
    label: 'Remove from wishlist',
    size: 'lg',
  },
};

// ─── style prop samples ──────────────────────────────────────────────────────

export const StyleBorderRadius: Story = {
  name: 'Style — Border Radius',
  args: {
    variant: 'primary',
    label: 'Button',
    size: 'large',
    style: { borderRadius: '24px' },
  },
};

export const StyleIconPadding: Story = {
  name: 'Style — Icon Padding',
  args: {
    variant: 'icon',
    icon: 'close',
    label: 'Close',
    size: 'md',
    style: { padding: '4px' },
  },
};

// ─── Interaction ─────────────────────────────────────────────────────────────

export const ClickInteraction: Story = {
  name: 'Click Interaction',
  args: {
    variant: 'primary',
    label: 'Add to bag',
    size: 'large',
    onClick: fn(),
  },
  play: async ({ canvasElement, args }) => {
    const canvas = within(canvasElement);
    const button = canvas.getByRole('button', { name: 'Add to bag' });
    await userEvent.click(button);
    await expect(args.onClick).toHaveBeenCalledOnce();
  },
};

export const IconClickInteraction: Story = {
  name: 'Icon Click Interaction',
  args: {
    variant: 'icon',
    icon: 'bag',
    label: 'Add to bag',
    size: 'lg',
    onClick: fn(),
  },
  play: async ({ canvasElement, args }) => {
    const canvas = within(canvasElement);
    const button = canvas.getByRole('button', { name: 'Add to bag' });
    await userEvent.click(button);
    await expect(args.onClick).toHaveBeenCalledOnce();
  },
};

