      <ZimmNavItem label="Clothing" href="#" inverse />
      <ZimmNavItem label="Accessories" href="#" inverse />
      <ZimmNavItem label="Collections" href="#" inverse />
      <ZimmNavItem label="Z.Immerse" href="#" inverse />
