      <ZimmNavItem label="Clothing" href="#" />
      <ZimmNavItem label="Accessories" href="#" />
      <ZimmNavItem label="Collections" href="#" />
      <ZimmNavItem label="Z.Immerse" href="#" />
    </Box>
  ),
};

// ─── Interaction ─────────────────────────────────────────────────────────────

export const KeyboardFocus: Story = {
  name: 'Keyboard Focus',
  args: { label: 'New', href: '#' },
