     1	/**
     2	 * Recipe guards — regression tests for three failure modes that reached a feature branch
     3	 * despite passing `tsc`, `eslint`, `vitest`, CodeRabbit and the Storybook a11y run.
     4	 *
     5	 * All three share a shape: the value is a *valid* `SystemStyleObject` entry, so TypeScript is
     6	 * satisfied; no lint rule covers it; and nothing asserts layout. Each one renders plausible,
     7	 * wrong output that is only visible by opening the page.
     8	 *
     9	 *   1. A spacing-scale key on a sizing property. Chakra resolves `width`/`height`/`boxSize`
    10	 *      through `theme.sizes`, not `theme.space`. The Zimmermann named scale is registered as
    11	 *      `space` only (deliberately — see foundation/sizes.ts), so `width: 'xl'` silently reads
    12	 *      Chakra's default `sizes.xl` = 36rem. It shipped a 576px icon and collapsed the footer.
    13	 *
    14	 *   2. A recipe key that collides with a base SFCC recipe. `theme/index.ts` composes with
    15	 *      `extendTheme(baseTheme, overrides)`, which DEEP MERGES — a recipe named `Footer` does
    16	 *      not replace SFCC's `Footer`, it inherits it. Shared part names then pick up base
    17	 *      properties, and a key you add that the base lacks is appended last, so a CSS shorthand
    18	 *      can silently reset a longhand the base declared earlier.
    19	 *
    20	 *   3. A bare scale key inside a compound shorthand. Chakra resolves a token only when it is
    21	 *      the entire value; `padding: 'xs 0'` is emitted verbatim, the browser rejects the
    22	 *      declaration, and the padding does not apply at all.
    23	 */
    24	import { describe, expect, test } from 'vitest';
    25	import theme from '../index';
    26	import { components } from './index';
    27	import { spacing } from '../foundation/spacing';
    28	
    29	const SPACING_KEYS = Object.keys(spacing);
    30	
    31	const SIZING_PROPS = new Set([
    32	  'width',
    33	  'height',
    34	  'minWidth',
    35	  'maxWidth',
    36	  'minHeight',
    37	  'maxHeight',
    38	  'boxSize',
    39	  'w',
    40	  'h',
    41	  'minW',
    42	  'maxW',
    43	  'minH',
    44	  'maxH',
    45	]);
    46	
    47	/** Properties that resolve through `theme.space`, where a bare scale key is correct. */
    48	const SPACE_SHORTHANDS = new Set(['padding', 'margin', 'inset', 'gap', 'p', 'm']);
    49	
    50	type Found = { recipe: string; path: string; prop: string; value: string };
    51	
    52	/** Recursively walk a style object, including nested media queries and pseudo-selectors. */
    53	const walk = (node: unknown, recipe: string, path: string, hit: (f: Found) => void): void => {
    54	  if (node === null || typeof node !== 'object') return;
    55	  for (const [key, value] of Object.entries(node as Record<string, unknown>)) {
    56	    const here = path ? `${path}.${key}` : key;
    57	    if (value !== null && typeof value === 'object') {
    58	      walk(value, recipe, here, hit);
    59	    } else if (typeof value === 'string') {
    60	      hit({ recipe, path, prop: key, value });
    61	    }
    62	  }
    63	};
    64	
    65	/** baseStyle may be a plain object or a function of props (see zimmTextInput). */
    66	const resolveBaseStyle = (recipe: Record<string, unknown>): unknown => {
    67	  const bs = recipe.baseStyle;
    68	  if (typeof bs !== 'function') return bs;
    69	  return (bs as (p: Record<string, unknown>) => unknown)({
    70	    inverse: false,
    71	    disabled: false,
    72	    hasError: false,
    73	    focused: false,
    74	    filled: false,
    75	    theme,
    76	    colorMode: 'light',
    77	  });
    78	};
    79	
    80	const collect = (): Found[] => {
    81	  const found: Found[] = [];
    82	  for (const [name, recipe] of Object.entries(components)) {
    83	    const r = recipe as unknown as Record<string, unknown>;
    84	    for (const section of [resolveBaseStyle(r), r.variants, r.sizes]) {
    85	      walk(section, name, '', (f) => found.push(f));
    86	    }
    87	  }
    88	  return found;
    89	};
    90	
    91	describe('recipe guards', () => {
    92	  test('no sizing property uses a bare spacing-scale key', () => {
    93	    const offenders = collect()
    94	      .filter((f) => SIZING_PROPS.has(f.prop) && SPACING_KEYS.includes(f.value))
    95	      .map((f) => `${f.recipe}.${f.path || 'baseStyle'}.${f.prop}: '${f.value}'`);
    96	
    97	    // `width: 'xl'` reads theme.sizes.xl (36rem), not space.xl (1.5rem).
    98	    // Use var(--zimm-scale-*), an imported constant, or an explicit unit instead.
    99	    expect(offenders).toEqual([]);
   100	  });
   101	
   102	  test('no compound shorthand contains a bare scale key', () => {
   103	    const offenders = collect()
   104	      .filter((f) => {
   105	        if (!SPACE_SHORTHANDS.has(f.prop)) return false;
   106	        if (!f.value.includes(' ')) return false; // single token is fine
   107	        // Split on whitespace outside var(...) and look for a bare scale key.
   108	        const parts = f.value.replace(/var\([^)]*\)/g, 'VAR').split(/\s+/);
   109	        return parts.some((part) => SPACING_KEYS.includes(part));
   110	      })
   111	      .map((f) => `${f.recipe}.${f.path || 'baseStyle'}.${f.prop}: '${f.value}'`);
   112	
   113	    // Chakra resolves a token only as a whole value. `padding: 'xs 0'` is emitted verbatim
   114	    // and the browser drops the declaration. Use paddingY/paddingX or a var() instead.
   115	    expect(offenders).toEqual([]);
   116	  });
   117	
   118	  test('no recipe silently inherits a base SFCC recipe of the same name', () => {
   119	    // extendTheme DEEP MERGES. These three intentionally share a base key: Button wants the
   120	    // base variants, and Header/ListMenu are partial overrides of components whose other
   121	    // parts we still rely on. Anything else must be namespaced (e.g. ZimmFooter, not Footer).
   122	    const INTENTIONAL_MERGES = ['Button', 'Header', 'ListMenu'];
   123	
   124	    const unexpected = Object.keys(components)
   125	      .filter((name) => !INTENTIONAL_MERGES.includes(name))
   126	      .filter((name) => {
   127	        const ours = resolveBaseStyle(components[name as keyof typeof components] as never) ?? {};
   128	        const merged = resolveBaseStyle((theme.components?.[name] ?? {}) as Record<string, unknown>) ?? {};
   129	        const ourKeys = new Set(Object.keys(ours as object));
   130	        // A key present after composition that we never declared came from the base theme.
   131	        return Object.keys(merged as object).some((k) => !ourKeys.has(k));
   132	      });
   133	
   134	    expect(unexpected).toEqual([]);
   135	  });
   136	});

