     1	import { describe, test, expect } from 'vitest';
     2	import { resolveBorderColour, resolveHoverBorderColour, resolveLabelColour, ZimmTextInput } from './zimmTextInput';
     3	
     4	/**
     5	 * The Figma colour cascade is the part of this recipe that can break without surfacing as a
     6	 * type or build error — a mis-ordered branch renders a plausible-but-wrong border. These
     7	 * assertions moved here from useZimmTextInputState.test.ts when the derivation moved out of
     8	 * the hook and into the theme.
     9	 */
    10	
    11	const base = { inverse: false, disabled: false, hasError: false, focused: false, filled: false };
    12	
    13	describe('ZimmTextInput — border colour precedence', () => {
    14	  test('disabled wins over error and filled', () => {
    15	    expect(resolveBorderColour({ ...base, disabled: true, hasError: true, filled: true })).toBe(
    16	      'var(--zimm-color-border-forms)',
    17	    );
    18	  });
    19	
    20	  test('error wins over focus and filled', () => {
    21	    expect(resolveBorderColour({ ...base, hasError: true, filled: true })).toBe('var(--zimm-color-status-error)');
    22	  });
    23	
    24	  test('a filled but unfocused field darkens to the focus colour', () => {
    25	    expect(resolveBorderColour({ ...base, filled: true })).toBe('var(--zimm-color-border-focus)');
    26	  });
    27	
    28	  // focused is its own branch, sitting between hasError and filled. In the light palette
    29	  // focus and filled resolve to the same colour, so only the empty-and-focused case can
    30	  // distinguish "the focus branch ran" from "it fell through to default".
    31	  test('an empty but focused field takes the focus colour, not the default', () => {
    32	    expect(resolveBorderColour({ ...base, focused: true })).toBe('var(--zimm-color-border-focus)');
    33	  });
    34	
    35	  test('an empty, unfocused, valid field uses the default border', () => {
    36	    expect(resolveBorderColour(base)).toBe('var(--zimm-color-border-forms)');
    37	  });
    38	
    39	  test('hover keeps the error colour when in error, otherwise darkens', () => {
    40	    expect(resolveHoverBorderColour({ ...base, hasError: true })).toBe('var(--zimm-color-status-error)');
    41	    expect(resolveHoverBorderColour(base)).toBe('var(--zimm-color-border-focus)');
    42	  });
    43	
    44	  test('inverse mode uses the inverse palette', () => {
    45	    expect(resolveBorderColour({ ...base, inverse: true })).toBe('var(--zimm-color-text-inverse)');
    46	    expect(resolveBorderColour({ ...base, inverse: true, hasError: true })).toBe('var(--zimm-color-status-error-bg)');
    47	  });
    48	});
    49	
    50	describe('ZimmTextInput — label colour', () => {
    51	  test('light mode: subtle once floated, default otherwise', () => {
    52	    expect(resolveLabelColour({ ...base, filled: true })).toBe('var(--zimm-color-text-secondary)');
    53	    expect(resolveLabelColour(base)).toBe('var(--zimm-color-text-default)');
    54	  });
    55	
    56	  test('inverse mode: grey once floated, white otherwise', () => {
    57	    expect(resolveLabelColour({ ...base, inverse: true, filled: true })).toBe('var(--zimm-color-text-inverse-grey)');
    58	    expect(resolveLabelColour({ ...base, inverse: true })).toBe('var(--zimm-color-text-inverse)');
    59	  });
    60	
    61	  test('disabled uses the subtle colour for the mode', () => {
    62	    expect(resolveLabelColour({ ...base, disabled: true })).toBe('var(--zimm-color-text-secondary)');
    63	    expect(resolveLabelColour({ ...base, disabled: true, inverse: true })).toBe('var(--zimm-color-text-inverse-grey)');
    64	  });
